func (q *Queries) ListManagedOOProposePriceLogs(ctx context.Context, arg ListManagedOOProposePriceLogsParams) ([]ListManagedOOProposePriceLogsRow, error) {
	rows, err := q.db.Query(ctx, listManagedOOProposePriceLogs, arg.BlockNumber, arg.OffsetValue, arg.LimitValue)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListManagedOOProposePriceLogsRow
	for rows.Next() {
		var i ListManagedOOProposePriceLogsRow
		if err := rows.Scan(
			&i.TxHash,
			&i.LogIndex,
			&i.BlockNumber,
			&i.BlockHash,
			&i.TxIndex,
			&i.ContractAddress,
			&i.Topic,
			&i.Requester,
			&i.Proposer,
			&i.Identifier,
			&i.RequestTimestamp,
			&i.AncillaryDataHex,
			&i.AncillaryDataText,
			&i.MarketID,
			&i.ProposedPrice,
			&i.ExpirationTimestamp,
			&i.Currency,
			&i.RawTopics,
			&i.RawData,
			&i.FetchedAt,
			&i.ConditionID,
			&i.EventSlug,
			&i.MarketSlug,
			&i.Question,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

